@contextmanager
def conectar_db():
    """Abre una conexión SQLite y la cierra siempre al terminar."""
    conexion = sqlite3.connect(DB_PATH, timeout=15)
    conexion.execute("PRAGMA foreign_keys = ON")
    try:
        yield conexion
        conexion.commit()
    except Exception:
        conexion.rollback()
        raise
    finally:
        conexion.close()



def base_datos_tiene_palabras(ruta):
    """Devuelve True si la ruta contiene una base SQLite válida con palabras."""
    if not os.path.isfile(ruta):
        return False

    conexion = None
    try:
        conexion = sqlite3.connect(ruta, timeout=10)
        existe_tabla = conexion.execute("""
            SELECT 1
            FROM sqlite_master
            WHERE type = 'table' AND name = 'palabras'
        """).fetchone()

        if not existe_tabla:
            return False

        total = conexion.execute(
            "SELECT COUNT(*) FROM palabras"
        ).fetchone()[0]
        return total > 0

    except sqlite3.DatabaseError:
        return False

    finally:
        if conexion is not None:
            conexion.close()


def instalar_base_datos_incluida():
    """Instala la base SQLite empaquetada en el ejecutable.

    En la primera ejecución del EXE, copia la base incluida desde la carpeta
    temporal de PyInstaller a %LOCALAPPDATA%\\DiccionarioInglesBritanico.
    En las siguientes ejecuciones conserva esa copia permanente, incluidos
    los cambios que el usuario haya hecho en su diccionario.

    En desarrollo (.py), la base continúa junto al proyecto y el CSV puede
    importarse automáticamente.
    """
    os.makedirs(CARPETA_DATOS, exist_ok=True)

    # Si la base permanente ya tiene palabras, se conserva y no se sobrescribe.
    if base_datos_tiene_palabras(DB_PATH):
        print("Base SQLite permanente encontrada. Se conserva.")
        return

    # En desarrollo, la base incluida y la de trabajo son el mismo archivo.
    # Si todavía no existe, preparar_base_datos() la creará y el CSV la poblará.
    misma_ruta = os.path.abspath(RUTA_DB_INCLUIDA) == os.path.abspath(DB_PATH)
    if misma_ruta and not getattr(sys, "frozen", False):
        return

    # El EXE debe contener la base SQLite ya poblada antes de compilar.
    if not base_datos_tiene_palabras(RUTA_DB_INCLUIDA):
        raise FileNotFoundError(
            "No se encontró una base SQLite válida y con palabras dentro del ejecutable.\n\n"
            f"Archivo esperado: {RUTA_DB_INCLUIDA}\n\n"
            "Antes de compilar, ejecutá el programa .py, comprobá que cargó las palabras, "
            "cerralo y compilá incluyendo DICCIONARO.db con: \n"
            'py -m PyInstaller --noconfirm --clean --onefile --windowed '
            '--name DiccionarioIngles --add-data "DICCIONARO.db;." diccionario_ingles_britanico.py'
        )

    # Copia primero a un archivo temporal para evitar dejar una base incompleta.
    ruta_temporal = DB_PATH + ".tmp"
    try:
        shutil.copy2(RUTA_DB_INCLUIDA, ruta_temporal)
        os.replace(ruta_temporal, DB_PATH)
    finally:
        # Si la copia falla, elimina el temporal incompleto.
        if os.path.exists(ruta_temporal):
            try:
                os.remove(ruta_temporal)
            except OSError:
                pass

    print(f"Base SQLite instalada en: {DB_PATH}")


def preparar_base_datos():
    """Crea las tablas del proyecto si todavía no existen."""
    os.makedirs(CARPETA_DATOS, exist_ok=True)

    with conectar_db() as conexion:
        # WAL mejora la convivencia entre lecturas y escrituras.
        conexion.execute("PRAGMA journal_mode = WAL")

        conexion.execute("""
            CREATE TABLE IF NOT EXISTS palabras (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                palabra_ingles TEXT NOT NULL COLLATE NOCASE UNIQUE,
                palabra_español TEXT,
                ejemplos TEXT
            )
        """)

        conexion.execute("""
            CREATE TABLE IF NOT EXISTS recursos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                nombre TEXT UNIQUE NOT NULL,
                contenido BLOB
            )
        """)

        conexion.execute("""
            CREATE TABLE IF NOT EXISTS verbos_irregulares (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                infinitivo TEXT NOT NULL COLLATE NOCASE UNIQUE,
                pasado_simple TEXT NOT NULL,
                participio_pasado TEXT NOT NULL,
                traduccion TEXT NOT NULL
            )
        """)

        # Esta tabla recuerda qué CSV ya se importó y su huella digital.
        # No contiene las palabras: las palabras están en la tabla palabras.
        conexion.execute("""
            CREATE TABLE IF NOT EXISTS control_importaciones (
                archivo TEXT PRIMARY KEY,
                huella TEXT NOT NULL,
                cantidad_registros INTEGER NOT NULL DEFAULT 0,
                fecha_importacion TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)


def normalizar(texto):
    """Quita espacios externos y convierte None en cadena vacía."""
    return ("" if texto is None else str(texto)).strip()


def normalizar_encabezado(texto):
    """Normaliza encabezados CSV: minúsculas, sin tildes ni signos."""
    texto = normalizar(texto).replace("\ufeff", "").lower()
    texto = unicodedata.normalize("NFKD", texto)
    texto = "".join(c for c in texto if not unicodedata.combining(c))
    return "".join(c for c in texto if c.isalnum())


def _leer_csv_flexible(ruta_csv):
    """
    Lee CSV en UTF-8, UTF-8 con BOM o codificaciones habituales de Windows.
    Detecta coma, punto y coma, tabulación o barra vertical.
    Devuelve (encabezados, filas_de_datos).
    """
    if not os.path.isfile(ruta_csv):
        raise FileNotFoundError(f"No existe el archivo:\n{ruta_csv}")

    contenido_bytes = open(ruta_csv, "rb").read()
    if not contenido_bytes:
        raise ValueError("El archivo CSV está vacío.")

    contenido = None
    for codificacion in ("utf-8-sig", "cp1252", "latin-1"):
        try:
            contenido = contenido_bytes.decode(codificacion)
            break
        except UnicodeDecodeError:
            continue

    if contenido is None:
        raise ValueError("No se pudo interpretar la codificación del CSV.")

    # Evaluamos los separadores posibles y elegimos el que produce
    # más columnas consistentes. Esto evita depender exclusivamente
    # de csv.Sniffer, que puede confundirse con ejemplos que contienen comas.
    mejor_separador = ","
    mejor_puntuacion = (-1, -1)

    for separador in (";", ",", "\t", "|"):
        lector_prueba = csv.reader(io.StringIO(contenido), delimiter=separador)
        filas_prueba = []
        for fila in lector_prueba:
            if any(normalizar(campo) for campo in fila):
                filas_prueba.append(fila)
            if len(filas_prueba) >= 30:
                break

        if not filas_prueba:
            continue

        anchos = [len(fila) for fila in filas_prueba]
        ancho_mas_comun = max(set(anchos), key=anchos.count)
        consistencia = anchos.count(ancho_mas_comun)
        puntuacion = (1 if ancho_mas_comun > 1 else 0, consistencia * ancho_mas_comun)

        if puntuacion > mejor_puntuacion:
            mejor_puntuacion = puntuacion
            mejor_separador = separador

    lector = csv.reader(io.StringIO(contenido), delimiter=mejor_separador)
    filas = [fila for fila in lector if any(normalizar(campo) for campo in fila)]

    if not filas:
        raise ValueError("El CSV no contiene registros.")

    encabezados = [normalizar(campo) for campo in filas[0]]
    filas_datos = filas[1:]

    return encabezados, filas_datos


# Nombres alternativos aceptados para cada campo del diccionario.
ALIAS_CSV_DICCIONARIO = {
    "ingles": {
        "palabraingles", "palabraeningles", "ingles", "english",
        "englishword", "word", "term", "headword", "entry", "palabra"
    },
    "espanol": {
        "palabraespanol", "palabraenespanol", "espanol", "spanish",
        "spanishword", "translation", "traduccion", "significado",
        "meaning", "definition", "definicion", "equivalente"
    },
    "ejemplos": {
        "ejemplos", "ejemplo", "examples", "example", "sentences",
        "sentence", "usage", "uso", "oraciones"
    }
}


def _detectar_columnas_diccionario(encabezados):
    """Devuelve los índices de las columnas inglés, español y ejemplos."""
    encabezados_norm = [normalizar_encabezado(h) for h in encabezados]
    posiciones = {}

    for campo, alias in ALIAS_CSV_DICCIONARIO.items():
        posiciones[campo] = next(
            (indice for indice, nombre in enumerate(encabezados_norm) if nombre in alias),
            None
        )

    if posiciones["ingles"] is None or posiciones["espanol"] is None:
        disponibles = ", ".join(str(h) for h in encabezados)
        raise ValueError(
            "No pude identificar las columnas de inglés y español.\n\n"
            "Encabezados encontrados: " + disponibles + "\n\n"
            "Usá encabezados como: palabra_ingles,palabra_español,ejemplos"
        )

    return posiciones


def _importar_filas_diccionario(encabezados, filas, conexion):
    """Inserta o actualiza palabras usando la estructura real de SQLite."""
    columnas = _detectar_columnas_diccionario(encabezados)
    indice_ingles = columnas["ingles"]
    indice_espanol = columnas["espanol"]
    indice_ejemplos = columnas["ejemplos"]

    procesadas = 0

    for fila in filas:
        # Evita errores si alguna línea tiene menos columnas.
        ingles = normalizar(fila[indice_ingles]) if indice_ingles < len(fila) else ""
        espanol = normalizar(fila[indice_espanol]) if indice_espanol < len(fila) else ""
        ejemplos = (
            normalizar(fila[indice_ejemplos])
            if indice_ejemplos is not None and indice_ejemplos < len(fila)
            else ""
        )

        if not ingles:
            continue

        # La clave UNIQUE palabra_ingles evita duplicados.
        # Si una traducción o ejemplo cambió en el CSV, se actualiza.
        conexion.execute("""
            INSERT INTO palabras (palabra_ingles, palabra_español, ejemplos)
            VALUES (?, ?, ?)
            ON CONFLICT(palabra_ingles) DO UPDATE SET
                palabra_español = CASE
                    WHEN excluded.palabra_español <> ''
                    THEN excluded.palabra_español
                    ELSE palabras.palabra_español
                END,
                ejemplos = CASE
                    WHEN excluded.ejemplos <> ''
                    THEN excluded.ejemplos
                    ELSE palabras.ejemplos
                END
        """, (ingles, espanol, ejemplos))
        procesadas += 1

    return procesadas


def cargar_diccionario_desde_csv():
    """
    Carga automáticamente mi_diccionario.csv a SQLite.

    - Primera ejecución: importa todas las filas válidas.
    - Siguientes ejecuciones: si el CSV no cambió, no hace nada.
    - Si el CSV cambió: agrega palabras nuevas y actualiza las existentes.
    - Si el CSV desaparece después de importar: la aplicación sigue usando
      las palabras que ya quedaron guardadas en la base de datos.
    """
    global ESTADO_CARGA_DICCIONARIO, ERROR_CARGA_DICCIONARIO
    ESTADO_CARGA_DICCIONARIO = ""
    ERROR_CARGA_DICCIONARIO = ""

    ruta_absoluta = os.path.abspath(RUTA_CSV_DICCIONARIO)

    # Primero comprobamos si el CSV existe. Si ya no existe, SQLite conserva
    # los datos previamente importados y la aplicación puede seguir funcionando.
    if not os.path.isfile(RUTA_CSV_DICCIONARIO):
        total = contar_palabras()
        if total > 0:
            ESTADO_CARGA_DICCIONARIO = (
                f"El CSV ya no está presente, pero hay {total} palabras guardadas en SQLite."
            )
            print(ESTADO_CARGA_DICCIONARIO)
            return 0

        ERROR_CARGA_DICCIONARIO = (
            "No se encontró mi_diccionario.csv en la carpeta del programa:\n"
            + RUTA_CSV_DICCIONARIO
        )
        print(ERROR_CARGA_DICCIONARIO)
        return -1

    try:
        # Se calcula el hash del archivo para saber si fue modificado.
        with open(RUTA_CSV_DICCIONARIO, "rb") as archivo:
            huella_actual = hashlib.sha256(archivo.read()).hexdigest()

        with conectar_db() as conexion:
            registro = conexion.execute("""
                SELECT huella
                FROM control_importaciones
                WHERE archivo = ?
            """, (ruta_absoluta,)).fetchone()

            # Si la huella coincide, el archivo ya está importado.
            if registro and registro[0] == huella_actual:
                total = conexion.execute(
                    "SELECT COUNT(*) FROM palabras"
                ).fetchone()[0]
                ESTADO_CARGA_DICCIONARIO = (
                    f"Diccionario listo: {total} palabras guardadas en SQLite."
                )
                print(ESTADO_CARGA_DICCIONARIO)
                return 0

            encabezados, filas = _leer_csv_flexible(RUTA_CSV_DICCIONARIO)
            cantidad = _importar_filas_diccionario(encabezados, filas, conexion)

            # Se registra el hash dentro de la misma transacción que los datos.
            conexion.execute("""
                INSERT INTO control_importaciones
                    (archivo, huella, cantidad_registros, fecha_importacion)
                VALUES (?, ?, ?, CURRENT_TIMESTAMP)
                ON CONFLICT(archivo) DO UPDATE SET
                    huella = excluded.huella,
                    cantidad_registros = excluded.cantidad_registros,
                    fecha_importacion = CURRENT_TIMESTAMP
            """, (ruta_absoluta, huella_actual, cantidad))

            total = conexion.execute(
                "SELECT COUNT(*) FROM palabras"
            ).fetchone()[0]

        ESTADO_CARGA_DICCIONARIO = (
            f"Importación automática terminada: {cantidad} filas procesadas. "
            f"Total en la base: {total} palabras."
        )
        print(ESTADO_CARGA_DICCIONARIO)
        return cantidad

    except Exception as error:
        ERROR_CARGA_DICCIONARIO = str(error)
        print("Error al cargar el diccionario:", error)
        return -1


def obtener_palabra(palabra):
    """Busca una palabra exacta en la tabla palabras."""
    with conectar_db() as conexion:
        return conexion.execute("""
            SELECT palabra_ingles, palabra_español, ejemplos
            FROM palabras
            WHERE palabra_ingles = ? COLLATE NOCASE
        """, (normalizar(palabra),)).fetchone()


def buscar_en_base(texto, limite=60):
    """Busca palabras que comiencen con el texto ingresado."""
    texto = normalizar(texto)
    if not texto:
        return []

    with conectar_db() as conexion:
        filas = conexion.execute("""
            SELECT palabra_ingles
            FROM palabras
            WHERE palabra_ingles LIKE ? COLLATE NOCASE
            ORDER BY palabra_ingles
            LIMIT ?
        """, (texto + "%", limite)).fetchall()

    return [fila[0] for fila in filas]


def contar_palabras():
    """Devuelve la cantidad de palabras almacenadas en SQLite."""
    with conectar_db() as conexion:
        return conexion.execute("SELECT COUNT(*) FROM palabras").fetchone()[0]


def normalizar_encabezado_csv_antiguo(texto):
    """Alias de normalización para mantener compatibilidad con el importador."""
    return normalizar_encabezado(texto)


def importar_diccionario_o_verbos_csv(ruta_csv):
    """Importa manualmente un CSV de diccionario o de verbos irregulares."""
    if not ruta_csv:
        return 0

    encabezados, filas = _leer_csv_flexible(ruta_csv)
    encabezados_norm = [normalizar_encabezado(h) for h in encabezados]

    alias_verbos = {
        "infinitivo": {"infinitivo", "infinitive", "base", "baseform", "verb"},
        "pasado": {"pasadosimple", "pasado", "pastsimple", "simplepast", "past"},
        "participio": {"participiopasado", "participio", "pastparticiple", "participle"},
        "traduccion": {"traduccion", "traducciones", "espanol", "spanish", "meaning"}
    }

    posiciones_verbos = {
        campo: next(
            (i for i, nombre in enumerate(encabezados_norm) if nombre in alias),
            None
        )
        for campo, alias in alias_verbos.items()
    }

    # Si están las cuatro columnas de verbos, importa a verbos_irregulares.
    if all(posiciones_verbos[campo] is not None for campo in alias_verbos):
        cantidad = 0
        with conectar_db() as conexion:
            for fila in filas:
                valores = []
                for campo in ("infinitivo", "pasado", "participio", "traduccion"):
                    indice = posiciones_verbos[campo]
                    valores.append(normalizar(fila[indice]) if indice < len(fila) else "")

                if not valores[0]:
                    continue

                conexion.execute("""
                    INSERT INTO verbos_irregulares
                        (infinitivo, pasado_simple, participio_pasado, traduccion)
                    VALUES (?, ?, ?, ?)
                    ON CONFLICT(infinitivo) DO UPDATE SET
                        pasado_simple = excluded.pasado_simple,
                        participio_pasado = excluded.participio_pasado,
                        traduccion = excluded.traduccion
                """, tuple(valores))
                cantidad += 1
        return cantidad

    # Si no es un CSV de verbos, se interpreta como diccionario.
    with conectar_db() as conexion:
        return _importar_filas_diccionario(encabezados, filas, conexion)


