def cargar_verbos_iniciales():
    """Carga los verbos iniciales una sola vez, si la tabla está vacía."""
    with conectar_db() as conexion:
        total = conexion.execute(
            "SELECT COUNT(*) FROM verbos_irregulares"
        ).fetchone()[0]

        if total == 0:
            conexion.executemany("""
                INSERT OR IGNORE INTO verbos_irregulares
                    (infinitivo, pasado_simple, participio_pasado, traduccion)
                VALUES (?, ?, ?, ?)
            """, VERBOS_INICIALES)


def buscar_verbos(filtro=""):
    """Busca verbos por infinitivo, pasado, participio o traducción."""
    patron = f"%{normalizar(filtro)}%"
    with conectar_db() as conexion:
        return conexion.execute("""
            SELECT infinitivo, pasado_simple, participio_pasado, traduccion
            FROM verbos_irregulares
            WHERE infinitivo LIKE ? COLLATE NOCASE
               OR pasado_simple LIKE ? COLLATE NOCASE
               OR participio_pasado LIKE ? COLLATE NOCASE
               OR traduccion LIKE ? COLLATE NOCASE
            ORDER BY infinitivo
        """, (patron, patron, patron, patron)).fetchall()


