# 8° PASO: BOTÓN REDONDEADO PERSONALIZADO
# ============================================================
class RoundedButton(tk.Canvas):
    """Botón dibujado en Canvas para conservar el estilo redondeado."""
    def __init__(self, parent, width, height, radius, bgcolor, fgcolor,
                 text, command=None, hovercolor="#3FBFB3"):
        super().__init__(
            parent,
            width=width,
            height=height,
            bg=parent.cget("bg"),
            highlightthickness=0,
            bd=0
        )
        self.width = width
        self.height = height
        self.radius = radius
        self.bgcolor = bgcolor
        self.fgcolor = fgcolor
        self.hovercolor = hovercolor
        self.text = text
        self.command = command
        self.state = "normal"
        self.hover = False
        self.parentbg = parent.cget("bg")
        self.font = ("Georgia", 11, "italic")

        self.dibujar()
        self.bind("<ButtonRelease-1>", self.click)
        self.bind("<Enter>", self.enter)
        self.bind("<Leave>", self.leave)

    def dibujar(self):
        self.delete("all")
        w, h, r = self.width, self.height, self.radius
        color = self.hovercolor if self.hover and self.state == "normal" else self.bgcolor

        self.create_arc(0, 0, 2*r, 2*r, start=90, extent=90, fill=color, outline=color)
        self.create_arc(w-2*r, 0, w, 2*r, start=0, extent=90, fill=color, outline=color)
        self.create_arc(w-2*r, h-2*r, w, h, start=270, extent=90, fill=color, outline=color)
        self.create_arc(0, h-2*r, 2*r, h, start=180, extent=90, fill=color, outline=color)
        self.create_rectangle(r, 0, w-r, h, fill=color, outline=color)
        self.create_rectangle(0, r, w, h-r, fill=color, outline=color)
        self.create_text(w/2, h/2, text=self.text, fill=self.fgcolor, font=self.font)

    def click(self, event=None):
        if self.state == "normal" and self.command:
            self.command()

    def enter(self, event=None):
        if self.state == "normal":
            self.hover = True
            self.config(cursor="hand2")
            self.dibujar()

    def leave(self, event=None):
        self.hover = False
        self.config(cursor="")
        self.dibujar()

    def set_colors(self, bg, hover, fg=None, parentbg=None):
        self.bgcolor = bg
        self.hovercolor = hover
        if fg is not None:
            self.fgcolor = fg
        if parentbg is not None:
            self.parentbg = parentbg
        self.config(bg=self.parentbg)
        self.dibujar()

    def set_font(self, font):
        self.font = font
        self.dibujar()

    def set_state(self, state):
        self.state = state
        if state != "normal":
            self.hover = False
            self.config(cursor="arrow")
        self.dibujar()


# ============================================================
# 9° PASO: FUNCIONES DE BÚSQUEDA Y VISUALIZACIÓN LOCAL
# ============================================================
def mostrar_texto(texto):
    """Actualiza el cuadro principal de resultados, que es de solo lectura."""
    if texto_ejemplos is None:
        return
    texto_ejemplos.config(state="normal")
    texto_ejemplos.delete("1.0", tk.END)
    texto_ejemplos.insert(tk.END, texto)
    texto_ejemplos.config(state="disabled")


def mostrar_definicion(palabra):
    fila = obtener_palabra(palabra)
    if fila:
        ingles, espanol, ejemplos = fila
        resultado = (
            f"PALABRA: {ingles}\n\n"
            f"TRADUCCIÓN / DEFINICIÓN:\n{espanol or 'Sin traducción cargada.'}\n\n"
            f"EJEMPLOS:\n{ejemplos or 'Sin ejemplos cargados.'}"
        )
    else:
        resultado = "La palabra no está en tu diccionario local."
    mostrar_texto(resultado)


def actualizar_sugerencias(event=None):
    consulta = entry_nombre.get().strip()
    lista_de_palabras.delete(0, tk.END)
    if not consulta:
        return
    for palabra in buscar_en_base(consulta):
        lista_de_palabras.insert(tk.END, palabra)


def seleccionar_sugerencia(event=None):
    seleccion = lista_de_palabras.curselection()
    if not seleccion:
        return
    palabra = lista_de_palabras.get(seleccion[0])
    entry_nombre.delete(0, tk.END)
    entry_nombre.insert(0, palabra)
    mostrar_definicion(palabra)


def buscar_palabra():
    palabra = entry_nombre.get().strip()
    if not palabra:
        messagebox.showinfo("Búsqueda", "Escribí una palabra primero.")
        return

    if obtener_palabra(palabra):
        mostrar_definicion(palabra)
    else:
        coincidencias = buscar_en_base(palabra)
        lista_de_palabras.delete(0, tk.END)
        for item in coincidencias:
            lista_de_palabras.insert(tk.END, item)

        if coincidencias:
            mostrar_texto("No encontré una coincidencia exacta.\nEstas palabras empiezan igual:")
        else:
            mostrar_texto(
                "No encontré esa palabra en tu diccionario local.\n"
                "Podés consultar Internet o la IA."
            )


def limpiar():
    entry_nombre.delete(0, tk.END)
    lista_de_palabras.delete(0, tk.END)
    mostrar_texto("")
    entry_nombre.focus_set()


def importar_csv_accion():
    """Permite una importación manual opcional, sin afectar la carga automática."""
    ruta = filedialog.askopenfilename(
        title="Seleccionar archivo CSV",
        filetypes=[("Archivos CSV", "*.csv"), ("Todos los archivos", "*.*")]
    )
    if not ruta:
        return

    try:
        total = importar_diccionario_o_verbos_csv(ruta)
        actualizar_sugerencias()
        messagebox.showinfo(
            "Importación completada",
            f"Se procesaron {total} registros."
        )
    except Exception as error:
        messagebox.showerror("Error al importar CSV", str(error))


# ============================================================
# 10° PASO: CONSULTA A INTERNET EN SEGUNDO PLANO
# ============================================================
def consultar_fuentes_web(palabra):
    resultados = []

    if not REQUESTS_DISPONIBLE:
        return [("Internet", "Falta instalar requests. Ejecutá: pip install requests")]

    palabra_url = quote(normalizar(palabra))

    try:
        url = "https://api.dictionaryapi.dev/api/v2/entries/en/" + palabra_url
        respuesta = requests.get(url, timeout=(4, 8))

        if respuesta.status_code == 404:
            resultados.append(("Free Dictionary API", "No se encontró una definición exacta."))
        else:
            respuesta.raise_for_status()
            datos = respuesta.json()

            for entrada in datos[:2]:
                fonetica = entrada.get("phonetic", "")
                for significado in entrada.get("meanings", [])[:3]:
                    categoria = significado.get("partOfSpeech", "")
                    for definicion in significado.get("definitions", [])[:2]:
                        bloque = (
                            f"Categoría: {categoria}\n"
                            f"Definición: {definicion.get('definition', '')}"
                        )
                        if definicion.get("example"):
                            bloque += f"\nEjemplo: {definicion['example']}"
                        if fonetica:
                            bloque += f"\nFonética: {fonetica}"
                        resultados.append(("Free Dictionary API", bloque))

    except requests.RequestException as error:
        resultados.append(("Free Dictionary API", f"No se pudo consultar: {error}"))

    try:
        url = f"https://api.datamuse.com/words?sp={palabra_url}&max=8"
        respuesta = requests.get(url, timeout=(4, 8))
        respuesta.raise_for_status()
        datos = respuesta.json()
        sugerencias = [item.get("word", "") for item in datos if item.get("word")]
        if sugerencias:
            resultados.append(("Datamuse (sugerencias)", ", ".join(sugerencias)))

    except requests.RequestException as error:
        resultados.append(("Datamuse", f"No se pudo consultar: {error}"))

    return resultados


def buscar_en_internet():
    palabra = entry_nombre.get().strip()
    if not palabra:
        messagebox.showinfo("Internet", "Escribí una palabra primero.")
        return

    boton_internet.set_state("disabled")
    mostrar_texto("Consultando fuentes de Internet...\nLa búsqueda se está realizando en segundo plano.")

    def tarea():
        resultados = consultar_fuentes_web(palabra)
        ventana.after(0, lambda: mostrar_resultados_web(palabra, resultados))

    threading.Thread(target=tarea, daemon=True).start()


def mostrar_resultados_web(palabra, resultados):
    boton_internet.set_state("normal")
    texto = f"RESULTADOS ONLINE PARA: {palabra}\n" + "=" * 45 + "\n\n"

    if not resultados:
        texto += "No se encontraron resultados."
    else:
        for numero, (fuente, contenido) in enumerate(resultados, start=1):
            texto += f"{numero}. FUENTE: {fuente}\n{contenido}\n\n"

    mostrar_texto(texto)


# ============================================================
# 11° PASO: INTELIGENCIA ARTIFICIAL LOCAL (OLLAMA + QWEN)
# ============================================================
def analizar_con_ia():
    palabra = entry_nombre.get().strip()
    if not palabra:
        messagebox.showinfo("IA", "Escribí una palabra primero.")
        return

    if not REQUESTS_DISPONIBLE:
        messagebox.showerror("IA", "Falta instalar requests. Ejecutá: pip install requests")
        return

    fila = obtener_palabra(palabra)
    contexto = ""
    if fila:
        contexto = (
            f"Traducción/definición de la base local: {fila[1]}\n"
            f"Ejemplos: {fila[2]}\n"
        )

    boton_ia.set_state("disabled")
    mostrar_texto(
        "La IA está preparando la respuesta...\n\n"
        "La primera consulta puede tardar más porque el modelo debe cargarse en memoria."
    )

    def tarea():
        try:
            prompt = f"""Respondé en español. Sos un asistente didáctico de inglés británico.
Analizá esta palabra: {palabra}
{contexto}
Explicá de forma breve y clara:
1. Significados y categoría gramatical.
2. Uso habitual.
3. Dos ejemplos en inglés con traducción al español.
4. Diferencias británico/estadounidense solo si son relevantes y conocidas.
No inventes datos. Si no sabés algo, decilo.
/no_think"""

            respuesta = requests.post(
                URL_OLLAMA,
                json={
                    "model": MODELO_IA,
                    "prompt": prompt,
                    "stream": False,
                    "keep_alive": "10m",
                    "options": {
                        "temperature": 0.2,
                        "num_ctx": 1024,
                        "num_predict": 150,
                        "top_k": 20,
                        "top_p": 0.8
                    }
                },
                timeout=(5, 90)
            )
            respuesta.raise_for_status()
            datos = respuesta.json()
            resultado = datos.get("response", "Qwen no devolvió texto.").strip()
            if not resultado:
                resultado = "La IA terminó la consulta, pero no devolvió una respuesta. Probá nuevamente."

        except requests.ConnectionError:
            resultado = (
                "No se pudo conectar con Ollama.\n\n"
                "1. Instalá Ollama.\n"
                "2. Abrí Ollama.\n"
                "3. En la terminal ejecutá: ollama pull qwen3:1.7b\n"
                "4. Volvé a probar."
            )
        except requests.Timeout:
            resultado = (
                "La IA tardó más de lo permitido y se canceló la espera.\n\n"
                "Cerrá programas que consuman memoria y probá otra vez."
            )
        except (requests.RequestException, ValueError) as error:
            resultado = f"Ocurrió un error al consultar Ollama:\n{error}"

        ventana.after(0, lambda: mostrar_analisis_ia(resultado))

    threading.Thread(target=tarea, daemon=True).start()


def mostrar_analisis_ia(resultado):
    boton_ia.set_state("normal")
    mostrar_texto("ANÁLISIS DE QWEN\n" + "=" * 45 + "\n\n" + resultado)


# ============================================================
# 12° PASO: VENTANA GRANDE DE VERBOS IRREGULARES
# ============================================================
def abrir_ventana_verbos_irregulares():
    ventana_verbos = tk.Toplevel(ventana)
    ventana_verbos.title("Verbos irregulares - Inglés Británico")
    ventana_verbos.geometry("1200x750")
    ventana_verbos.minsize(850, 520)
    ventana_verbos.config(bg=NEGRO if tema_oscuro else Gris_niebla)
    ventanas_secundarias.append(ventana_verbos)

    def al_cerrar():
        if ventana_verbos in ventanas_secundarias:
            ventanas_secundarias.remove(ventana_verbos)
        ventana_verbos.destroy()

    ventana_verbos.protocol("WM_DELETE_WINDOW", al_cerrar)

    bg_ventana = NEGRO if tema_oscuro else Gris_niebla
    bg_panel = GRIS if tema_oscuro else BLANCO
    fg_texto = BLANCO_HUESO if tema_oscuro else Gris_carbón
    bg_header = GRIS_AZULADO if tema_oscuro else Azul_profundo
    fg_header = VERDE_TERMINAL if tema_oscuro else BLANCO

    encabezado = tk.Frame(ventana_verbos, bg=bg_header, height=80)
    encabezado.pack(fill="x")
    encabezado.pack_propagate(False)
    tk.Label(
        encabezado,
        text="IRREGULAR VERBS (BRITISH ENGLISH)",
        bg=bg_header,
        fg=fg_header,
        font=("Georgia", 24, "italic")
    ).pack(expand=True)

