def alternar_tema():
    global tema_oscuro
    tema_oscuro = not tema_oscuro
    aplicar_tema()


def aplicar_tema():
    """Actualiza los colores de los controles principales."""
    if ventana is None:
        return

    if tema_oscuro:
        fondo_win = NEGRO
        fondo_panel = GRIS
        texto_fg = BLANCO_HUESO
        banner_bg = GRIS_AZULADO
        banner_fg = VERDE_TERMINAL
        btn_tema.set_colors(AMARILLO, "#FFD54F", fg=NEGRO, parentbg=banner_bg)
        btn_tema.text = "Modo Claro"
    else:
        fondo_win = Gris_niebla
        fondo_panel = BLANCO
        texto_fg = Gris_carbón
        banner_bg = Azul_profundo
        banner_fg = BLANCO
        btn_tema.set_colors(GRIS_AZULADO, Azul_oscuro, fg=BLANCO, parentbg=banner_bg)
        btn_tema.text = "Modo Oscuro"

    btn_tema.dibujar()
    ventana.config(bg=fondo_win)
    frame_banner.config(bg=banner_bg)
    banner_label.config(bg=banner_bg, fg=banner_fg)

    # Actualiza Frames y Labels de la interfaz principal.
    # El banner se excluye para conservar su color independiente.
    def actualizar_widgets(contenedor):
        for hijo in contenedor.winfo_children():
            if hijo is frame_banner:
                continue
            if isinstance(hijo, tk.Frame):
                hijo.config(bg=fondo_win)
                actualizar_widgets(hijo)
            elif isinstance(hijo, tk.Label):
                hijo.config(bg=fondo_win, fg=texto_fg)

    actualizar_widgets(ventana)
    frame_banner.config(bg=banner_bg)
    banner_label.config(bg=banner_bg, fg=banner_fg)

    entry_nombre.config(bg=fondo_panel, fg=texto_fg, insertbackground=texto_fg)
    lista_de_palabras.config(
        bg=fondo_panel,
        fg=texto_fg,
        selectbackground=AZUL_SERENO if tema_oscuro else Azul_claro,
        selectforeground=BLANCO if tema_oscuro else Gris_carbón
    )
    texto_ejemplos.config(bg=fondo_panel, fg=texto_fg, insertbackground=texto_fg)

    for rb in (boton_ia, boton_internet, boton_importar_CSV, boton_verbos, btn_info):
        if rb is not None:
            rb.config(bg=fondo_win)
            rb.parentbg = fondo_win
            rb.dibujar()


