def cargar_banner_en_label(label_widget):
    global foto_banner

    if PIL_DISPONIBLE and CFP_402_64:
        try:
            datos_img = base64.b64decode(CFP_402_64)
            img = Image.open(BytesIO(datos_img))
            resampling = getattr(Image, "Resampling", Image).LANCZOS
            img = ImageOps.fit(img, (900, 85), method=resampling)
            foto_banner = ImageTk.PhotoImage(img)
            label_widget.config(image=foto_banner, text="")
            return
        except Exception as error:
            print("No se pudo cargar el banner:", error)

    label_widget.config(
        text="DICCIONARIO INGLÉS BRITÁNICO - ESPAÑOL",
        font=("Georgia", 20, "italic")
    )


